import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, mix, vec3, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const root = new THREE.Group();
  root.name = 'features-title-sprite';
  const inner = new THREE.Group();
  root.add(inner);

  // ---- bridging idiom for copy ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const headlineText = (headlineItem?.text ?? 'Features').replace(/[^\x00-\x7F]/g, '');
  const headlineFontSize = headlineItem?.typography?.fontSize ?? 96;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ---- atlas region aspect ----
  const rectW = 512;
  const rectH = 320;
  const aspect = rectW / rectH;
  const planeWidth = 3.0;
  const planeHeight = planeWidth / aspect;

  // ---- grain texture node (placeholder until async load resolves) ----
  const placeholderTex = new THREE.Texture();
  const grainTexNode = texture(placeholderTex);

  const inkColor = vec3(0.086, 0.086, 0.114); // #16161d
  const surfaceColor = vec3(0.043, 0.043, 0.063); // #0b0b10
  const accentColor = vec3(1.0, 0.1647, 0.2196); // #ff2a38

  const gradientNode = mix(surfaceColor, inkColor, uv().y);
  const grainSample = grainTexNode.r;
  const stripeMask = smoothstep(0.0, 0.015, uv().x).mul(smoothstep(0.03, 0.015, uv().x));

  const colorNode = gradientNode
    .add(vec3(1, 1, 1).mul(grainSample).mul(0.06))
    .add(accentColor.mul(stripeMask).mul(0.6));

  const backdropMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 1 });
  backdropMat.colorNode = colorNode;

  const backdropGeo = new THREE.PlaneGeometry(planeWidth, planeHeight);
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = 0;
  inner.add(backdrop);

  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.wrapS = THREE.ClampToEdgeWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;
      grainTexNode.value = tex;
      backdropMat.needsUpdate = true;
    })
    .catch(() => {});

  // ---- headline text (brightest element on this node) ----
  const textObj = ctx.fontAtlas.createText(headlineText, {
    fontSize: headlineFontSize,
    color: colors.paper,
    align: 'center',
  });
  textObj.position.set(0, 0.05, 0.02);
  inner.add(textObj);

  // ---- accent underline bar: small extruded 3D PBR object ----
  const barGeo = new THREE.BoxGeometry(1.1, 0.045, 0.045);
  const barMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    metalness: 0.4,
    roughness: 0.55,
    clearcoat: 0.2,
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 0.4,
  });
  const bar = new THREE.Mesh(barGeo, barMat);
  bar.position.set(0, -planeHeight * 0.28, 0.03);
  inner.add(bar);

  // ---- entrance motion: weighted rise-in + settle overshoot ----
  inner.position.y = -0.4;
  inner.scale.set(1, 1, 1);

  const tl = gsap.timeline();
  tl.fromTo(
    inner.position,
    { y: -0.4 },
    { y: 0, duration: 0.7, ease: 'power3.out' },
    0
  );
  tl.fromTo(
    inner.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0
  );
  tl.fromTo(
    backdropMat,
    { opacity: 0 },
    { opacity: 1, duration: 0.5, ease: 'power2.out' },
    0
  );

  // ---- apply any listed cinematic primitives (none configured, but honor contract) ----
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const applyFn = ctx.primitives?.[prim.name];
    if (typeof applyFn === 'function') {
      const handle = applyFn(inner, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    for (const h of primitiveHandles) {
      h.cleanup?.();
    }
    backdropGeo.dispose();
    backdropMat.dispose();
    barGeo.dispose();
    barMat.dispose();
    placeholderTex.dispose();
    if (grainTexNode.value && grainTexNode.value !== placeholderTex) {
      grainTexNode.value.dispose();
    }
    if (typeof textObj.userData?.cleanup === 'function') {
      textObj.userData.cleanup();
    }
  };

  return root;
}
